import{_ as o,l,o as a,c as n,v as t,p as s,x as i,d as h,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"筛选与信息租金","description":"","frontmatter":{"title":"筛选与信息租金","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/screening-rent.md","filePath":"econ/screening-rent.md","lastUpdated":1789023840000}'),c={name:"econ/screening-rent.md"};function E(_,e,B,m,q,C){const r=l("Mermaid");return a(),n("div",null,[e[1]||(e[1]=t('<h1 id="筛选与信息租金" tabindex="-1">筛选与信息租金 <a class="header-anchor" href="#筛选与信息租金" aria-label="Permalink to &quot;筛选与信息租金&quot;">​</a></h1><div class="epigraph"><p>不知情的一方提供合同菜单；为让高风险（或低成本）类型说真话，必须留给他们信息租金，并扭曲低类型的数量。</p><footer>—— 据 Rothschild and Stiglitz, QJE, 1976；Mirrlees, RES, 1971 整理</footer></div><p><a href="/econ/pooling-separating">上一课</a>（混同与分离）。是知情者先烧信号。缺口是时序反过来：不知情者先设计一组合同，类型自己选。保险、非线性定价、最优所得税都是这张菜单。本课钉激励相容、信息租金与「只扭曲低类型」，不把隐藏行动写成道德风险。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>类型 \\(\\theta\\) 仍是私信息，但合同由不知情者（或竞争中的保险公司、垄断卖方）提出。直接机制：对每个报出的 \\(\\hat\\theta\\) 给一包 \\((q(\\hat\\theta),t(\\hat\\theta))\\)。激励相容（IC）要求真类型愿意报自己。单交叉下，局部 IC 变成单调性加积分条件；高类型的租金由其「模仿低类型能得到的好处」决定，通常严格为正——否则他会假装成低类型，吃更便宜的合同。</p><p>效率对照：完全信息应对每类提供其第一最佳 \\(q^*(\\theta)\\)。隐藏类型后，给低类型提供 \\(q^*(\\theta_L)\\) 会让高类型的模仿太甜，只好把 \\(q(\\theta_L)\\) 向下扭曲，降低模仿价值，从而少付租金。高类型的 \\(q\\) 往往仍第一最佳（无扭曲在上）。租金是效率代价的来源：计划者或企业拿租金换配置。</p><h3 id="竞争筛选可以没有均衡" tabindex="-1">竞争筛选可以没有均衡 <a class="header-anchor" href="#竞争筛选可以没有均衡" aria-label="Permalink to &quot;竞争筛选可以没有均衡&quot;">​</a></h3><p>Rothschild–Stiglitz：竞争保险各出一份合同，分离的候选是低风险全保险、高风险部分保险。但可能有一份新合同把低风险撇走，均衡空。这与<a href="/econ/ge-existence">存在性</a>的凸连续不同：策略空间是合同，偏离是引入新菜单。信号时序下 Riley 等精炼可救；本课记下「菜单竞争不必有均衡」。</p><p><span class="marginnote">信息租金不是寻租的骂名。它是 IC 的影子价格：你无法既让人说真话，又不让优势类型分走一块剩余。Mirrlees 所得税里，高能力的边际税在顶上为零，正是「无扭曲在上」。</span></p><p>参与约束通常只绑低类型：高类型拿到租金后，更愿意进来。 若把高类型的 IR 也抽干，IC 会破。这与道德风险里「事前 IR 绑紧、无事前租金」不是同一句话。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：两类型、拟线性、单交叉。不知情者最大化利润或社会剩余，约束是 IC 与参与（IR）。绑紧的通常是：低类型 IR、高类型相对低类型的 IC。由此解出租金公式与 \\(q(\\theta_L)\\lt q^*(\\theta_L)\\)。</p><p>垄断卖方对消费者类型筛选（Maskin–Riley、Mussa–Rosen）同一骨架：数量或质量对低类型扭曲，高类型留下租金。公共品与<a href="/econ/theory-of-second-best">次优</a>的交汇：不能用总额税抽走租金时，扭曲税与数量扭曲一起出现。</p>',13)),(a(),s(p,null,{default:i(()=>[d(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20SIG%5B%22%E4%BF%A1%E5%8F%B7%EF%BC%9A%E7%9F%A5%E6%83%85%E8%80%85%E5%85%88%E5%8A%A8%22%5D%20--%3E%20SCR%5B%22%E7%AD%9B%E9%80%89%EF%BC%9A%E4%B8%8D%E7%9F%A5%E6%83%85%E8%80%85%E5%87%BA%E8%8F%9C%E5%8D%95%22%5D%0A%20%20SCR%20--%3E%20IC%5B%22IC%EF%BC%9A%E8%AF%B4%E7%9C%9F%E8%AF%9D%22%5D%0A%20%20IC%20--%3E%20RENT%5B%22%E4%BC%98%E5%8A%BF%E7%B1%BB%E5%9E%8B%E6%8B%BF%E8%B5%B0%E7%A7%9F%E9%87%91%22%5D%0A%20%20RENT%20--%3E%20DIST%5B%22%E6%89%AD%E6%9B%B2%E4%BD%8E%E7%B1%BB%E5%9E%8B%E7%9A%84%20q%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[h(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么必须留租金：完全抽干高类型，会使他的支付与低类型合同一样好，他改选低类型合同。要把他按住，要么给他更好的包（租金），要么把低类型的包改得对他更无吸引力（扭曲 \\(q_L\\)）。最优是两者搭配，直到多留一块租金的成本等于多扭曲一点 \\(q_L\\) 的收益。这与<a href="/econ/theory-of-second-best">次优</a>同一逻辑：IC 是锁死的约束，第一最佳的 \\(q^*(\\theta_L)\\) 不再可欲。</p><p>与柠檬、信号的分工：柠檬几乎没有工具；信号由知情者承担耗散成本；筛选由不知情者承担配置扭曲与租金。同一隐藏类型，时序与工具不同，福利账不同。后课若把「类型」换成「签约后才选的努力」，租金故事要改写成风险补偿，约束从报类型换成选行动。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>连续类型用积分 IC，哈密顿方法，本课不写。多维类型，单交叉不够，铁幕条件复杂。竞争筛选的存在性是开放结构，Wilson 预期均衡、Miyazaki–Wilson 交叉补贴是不同解。隐藏行动加隐藏类型是混合模型，下一课先把行动藏起来。</p><p>拟线性把租金写成货币，收入效应不搅数量。没有拟线性，扭曲公式还要加收入项，本课不写。</p><p>后课默认：筛选 = 菜单 + IC + 租金；效率损失来自为省租金而扭曲低类型。</p><h3 id="无扭曲在上-竞争却可能无均衡" tabindex="-1">无扭曲在上，竞争却可能无均衡 <a class="header-anchor" href="#无扭曲在上-竞争却可能无均衡" aria-label="Permalink to &quot;无扭曲在上，竞争却可能无均衡&quot;">​</a></h3><p>高类型的 \\(q\\) 停在第一最佳，不是因为更值得，而是再扭曲他省不下模仿租金。连续类型时只有顶上无扭曲；中间类型仍被扭。Mirrlees 顶层边际税为零，是这句的税率版。竞争出菜单时这份租金可能被撇脂竞争掉，均衡也可以空，那是 Rothschild–Stiglitz 的存在性缺口：自由进入加一份合同一份利润，分离候选会被新合同把低风险撇走。垄断委托人承诺菜单，通常有解。</p><p>拟线性把租金写成货币，收入效应不搅数量。没有拟线性，扭曲公式还要加收入项，本课不写。</p><p><span class="marginnote">信息租金是 IC 的影子价格。你无法既让人说真话，又不让优势类型分走一块剩余。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>不知情者先动，用菜单筛选；IC 迫使留下信息租金。</li><li>典型：低类型数量扭曲，高类型无扭曲。</li><li>竞争出菜单可能无均衡（Rothschild–Stiglitz）。</li><li>信号耗散成本，筛选扭曲配置，时序决定哪一种。</li><li>出处：Rothschild and Stiglitz, <em>QJE</em> 1976；Mirrlees, <em>RES</em> 1971。</li></ul>',13))])}const A=o(c,[["render",E]]);export{u as __pageData,A as default};
